create table if not exists public.nature_learning_cards_i18n (
  slug text not null references public.nature_learning_cards(slug) on delete cascade,
  lang text not null,
  title text,
  body text,
  key_points text[],
  tip text,
  safety_caveat text,
  verified boolean not null default false,
  created_at timestamptz not null default now(),
  primary key (slug, lang)
);

alter table public.nature_learning_cards_i18n enable row level security;

drop policy if exists "nature_learning_i18n_read" on public.nature_learning_cards_i18n;
create policy "nature_learning_i18n_read" on public.nature_learning_cards_i18n
  for select to anon, authenticated using (true);

revoke insert, update, delete on public.nature_learning_cards_i18n from anon, authenticated, public;

